const root = $input.first().json;
const binary = $input.first().binary || {};

const envelope = root.body || {};
const data = envelope.data || {};
const message = data.message || {};
const key = data.key || {};

// ---------- TEXT (WhatsApp) ----------
const conversation = message.conversation || null;
const extendedText = message.extendedTextMessage?.text || null;
const imageCaption = message.imageMessage?.caption || null;
const documentCaption = message.documentMessage?.caption || null;
let textContent = conversation || extendedText || imageCaption || documentCaption || null;
let hasText = !!textContent;

// ---------- IMAGE / PDF (WhatsApp) ----------
const imageMessage =
  message.imageMessage ||
  message?.viewOnceMessage?.message?.imageMessage ||
  message?.ephemeralMessage?.message?.imageMessage ||
  null;
let hasImage = !!imageMessage;
const resolvedImageCaption = imageMessage?.caption || '';

const documentMessage =
  message.documentMessage ||
  message?.viewOnceMessage?.message?.documentMessage ||
  message?.ephemeralMessage?.message?.documentMessage ||
  null;
const mimeType = documentMessage?.mimetype?.toLowerCase() || '';
const fileName = documentMessage?.fileName?.toLowerCase() || '';
let hasPdf = !!(documentMessage && (mimeType.includes('pdf') || fileName.endsWith('.pdf')));

// ---------- DIRECT UPLOAD (multipart from admin frontend) ----------
let directUpload = false;
let directBinary = null;
let directMime = null;
let directFileName = null;

for (const [propName, b] of Object.entries(binary)) {
  if (!b || !b.mimeType) continue;
  const mt = String(b.mimeType).toLowerCase();
  const fn = String(b.fileName || '').toLowerCase();
  if (mt.startsWith('image/')) {
    hasImage = true;
    directUpload = true;
    directBinary = b;
    directMime = mt;
    directFileName = fn;
    break;
  }
  if (mt === 'application/pdf' || fn.endsWith('.pdf')) {
    hasPdf = true;
    directUpload = true;
    directBinary = b;
    directMime = mt;
    directFileName = fn;
    break;
  }
}
// Extraction du nom de profil WhatsApp et du numéro de l'expéditeur dans le groupe
const senderName = data.pushName || envelope.pushName || envelope.data?.pushName || null;
const participantJid = key.participant || data.participant || key.remoteJid || '';
const rawPhone = participantJid.split('@')[0].replace(/\D/g, '');
const senderPhone = rawPhone ? `0${rawPhone.replace(/^213/, '')}` : null; // format local: 0550...

// Multipart text field from direct upload (admin frontend)
const directText = (root && root.body && typeof root.body.text === 'string') ? root.body.text.trim() : '';
if (directText) {
  if (!textContent) textContent = directText;
  hasText = true;
  directUpload = true;
}

const jobId = 'job_' + Date.now() + '_' + Math.random().toString(36).substring(2, 11);
const senderJid = key.remoteJid || envelope.sender || (directUpload ? 'manual_upload' : 'unknown');

// ---------- HASH UNIQUE SHA-256 (Média + Légende) ----------
const crypto = require('crypto');
let contentHash = null;
let mediaType = 'text';
const normCaption = (textContent || resolvedImageCaption || '').trim().toLowerCase().replace(/\s+/g, ' ');

if (hasImage) {
  mediaType = 'image';
  if (directUpload && directBinary?.data) {
    const buf = Buffer.from(directBinary.data, 'base64');
    const fsha = crypto.createHash('sha256').update(buf).digest('hex');
    contentHash = crypto.createHash('sha256').update('img:' + fsha + ':' + normCaption).digest('hex');
  } else if (imageMessage?.fileSha256) {
    const raw = imageMessage.fileSha256;
    const fsha = typeof raw === 'string' ? raw : (Array.isArray(raw?.data) ? Buffer.from(raw.data).toString('base64') : JSON.stringify(raw));
    contentHash = crypto.createHash('sha256').update('img:' + fsha + ':' + normCaption).digest('hex');
  } else if (imageMessage?.mediaKey) {
    contentHash = crypto.createHash('sha256').update('img:' + JSON.stringify(imageMessage.mediaKey) + ':' + normCaption).digest('hex');
  }
} else if (hasPdf) {
  mediaType = 'pdf';
  if (directUpload && directBinary?.data) {
    const buf = Buffer.from(directBinary.data, 'base64');
    const fsha = crypto.createHash('sha256').update(buf).digest('hex');
    contentHash = crypto.createHash('sha256').update('pdf:' + fsha + ':' + normCaption).digest('hex');
  } else if (documentMessage?.fileSha256) {
    const raw = documentMessage.fileSha256;
    const fsha = typeof raw === 'string' ? raw : (Array.isArray(raw?.data) ? Buffer.from(raw.data).toString('base64') : JSON.stringify(raw));
    contentHash = crypto.createHash('sha256').update('pdf:' + fsha + ':' + normCaption).digest('hex');
  }
} else if (hasText && normCaption.length > 20) {
  mediaType = 'text';
  contentHash = crypto.createHash('sha256').update('txt:' + normCaption).digest('hex');
}

const out = {
  json: {
    jobId,
    senderJid,
    senderName,   // <--- PLAN B : Nom affiché de la personne (pushName)
    senderPhone,  // <--- PLAN C : Numéro WhatsApp
    messageId: key.id || null,
    remoteJid: key.remoteJid || null,
    fromMe: key.fromMe || false,
    instanceName: envelope.instance || null,
    originalPayload: root,
    originalBody: envelope,
    hasText,
    hasImage,
    hasPdf,
    directUpload,
    directMime,
    directFileName,
    text: textContent,
    imageCaption: resolvedImageCaption,
    image: hasImage ? imageMessage : null,
    pdf: hasPdf ? documentMessage : null,
    _content_hash: contentHash,
    _media_type: mediaType
  }
};

if (directUpload && directBinary) {
  out.binary = {};
  if (hasImage) out.binary.image = directBinary;
  if (hasPdf) out.binary.document = directBinary;
}

return [out];

// ============================================================================
// NŒUD : Collect & Dynamic Merge (HARMONISÉ - cohérent avec Format Text)
// PLACE : Après Merge 2, AVANT Compute Slugs
//
// RÔLE : Fusionner les outputs des 3 branches (texte, image, PDF) en un seul
//        payload cohérent avec normalisation FR + dédup.
// ============================================================================

const items = $input.all().map(i => i.json);

// ----------------------------------------------------------------------------
// HELPERS (mêmes fonctions que Format Text Result)
// ----------------------------------------------------------------------------
function normalizeNumber(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string') {
    const cleaned = v.trim().replace(/\s+/g, '').replace(/,/g, '.').replace(/[^\d.-]/g, '');
    if (!cleaned || cleaned === '.' || cleaned === '-' || cleaned === '-.') return null;
    const num = Number(cleaned);
    return Number.isFinite(num) ? num : null;
  }
  return null;
}

// ============================================================
// normalizeItinerary : garantit toujours un tableau [{day,title,items}]
// Convertit l'ancien format {day_1,day_2} ET valide le nouveau
// ============================================================
function normalizeItinerary(raw) {
  if (!raw) return [];

  // Découpe une phrase en items logiques
  function splitIntoItems(text) {
    if (typeof text !== 'string') return [];
    const t = text.trim();
    if (!t) return [];
    // Découpe sur , ; / . / retours ligne, garde segments non vides
    const parts = t
      .split(/[\n•;]|(?:,\s)|(?:\.\s)|(?:\s\/\s)/)
      .map(s => s.replace(/^[\s\-–—*.]+|[\s\-–—*.]+$/g, '').trim())
      .filter(s => s.length > 1);
    return parts.length > 0 ? parts : [t];
  }

  // Titre court depuis le 1er segment
  function makeTitle(items, fallback) {
    const first = (items && items[0]) ? items[0] : fallback;
    if (!first) return 'Journée';
    let title = String(first).trim();
    if (title.length > 60) title = title.slice(0, 57).trim() + '...';
    return title;
  }

  // ── Déjà un tableau
  if (Array.isArray(raw)) {
    const out = [];
    raw.forEach((entry, idx) => {
      if (!entry) return;
      // Entrée déjà au bon format
      if (typeof entry === 'object' && !Array.isArray(entry)) {
        let items = [];
        if (Array.isArray(entry.items)) {
          items = entry.items.map(x => String(x).trim()).filter(Boolean);
        } else if (typeof entry.description === 'string') {
          items = splitIntoItems(entry.description);
        } else if (typeof entry.text === 'string') {
          items = splitIntoItems(entry.text);
        }
        const dayNum = Number.isFinite(entry.day) ? entry.day
          : (parseInt(entry.day, 10) || idx + 1);
        const title = (typeof entry.title === 'string' && entry.title.trim())
          ? entry.title.trim() : makeTitle(items, null);
        if (items.length === 0 && !title) return;
        out.push({ day: dayNum, title: title || makeTitle(items, 'Journée'), items: items.length ? items : [title] });
      } else if (typeof entry === 'string' && entry.trim()) {
        const items = splitIntoItems(entry);
        out.push({ day: idx + 1, title: makeTitle(items, null), items });
      }
    });
    return out.map((d, i) => ({ day: i + 1, title: d.title, items: d.items }));
  }

  // ── Objet ancien format {day_1, day_2} ou {jour 1, ...}
  if (typeof raw === 'object') {
    const entries = Object.entries(raw)
      .filter(([, v]) => typeof v === 'string' ? v.trim() : (v && typeof v === 'object'));
    // Trie par numéro de jour extrait de la clé
    entries.sort((a, b) => {
      const na = parseInt(String(a[0]).replace(/\D/g, ''), 10) || 0;
      const nb = parseInt(String(b[0]).replace(/\D/g, ''), 10) || 0;
      return na - nb;
    });
    const out = [];
    entries.forEach(([key, value], idx) => {
      const dayNum = parseInt(String(key).replace(/\D/g, ''), 10) || idx + 1;
      let items, title;
      if (typeof value === 'string') {
        items = splitIntoItems(value);
        title = makeTitle(items, null);
      } else if (value && typeof value === 'object') {
        items = Array.isArray(value.items)
          ? value.items.map(x => String(x).trim()).filter(Boolean)
          : splitIntoItems(value.description || value.text || '');
        title = (typeof value.title === 'string' && value.title.trim())
          ? value.title.trim() : makeTitle(items, null);
      } else {
        return;
      }
      if (items.length === 0) return;
      out.push({ day: dayNum, title, items });
    });
    return out.map((d, i) => ({ day: i + 1, title: d.title, items: d.items }));
  }

  return [];
}

function uniqueStrings(arr) {
  return [...new Set((arr || []).filter(v => typeof v === 'string' && v.trim() !== ''))];
}

function stripAccents(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

// MAPPING ANGLAIS → FRANÇAIS POUR LES PAYS
const COUNTRY_EN_TO_FR = {
  'azerbaijan': 'Azerbaïdjan', 'turkey': 'Turquie', 'turkiye': 'Turquie', 'türkiye': 'Turquie',
  'morocco': 'Maroc', 'tunisia': 'Tunisie', 'egypt': 'Égypte', 'spain': 'Espagne',
  'france': 'France', 'italy': 'Italie', 'greece': 'Grèce', 'cyprus': 'Chypre',
  'portugal': 'Portugal', 'malaysia': 'Malaisie', 'thailand': 'Thaïlande',
  'maldives': 'Maldives', 'mauritius': 'Maurice', 'seychelles': 'Seychelles',
  'indonesia': 'Indonésie', 'china': 'Chine', 'japan': 'Japon',
  'south korea': 'Corée du Sud', 'singapore': 'Singapour',
  'united arab emirates': 'Émirats Arabes Unis', 'uae': 'Émirats Arabes Unis', 'dubai': 'Émirats Arabes Unis',
  'qatar': 'Qatar', 'saudi arabia': 'Arabie Saoudite', 'jordan': 'Jordanie',
  'lebanon': 'Liban', 'oman': 'Oman', 'india': 'Inde', 'sri lanka': 'Sri Lanka',
  'vietnam': 'Vietnam', 'algeria': 'Algérie', 'germany': 'Allemagne',
  'austria': 'Autriche', 'switzerland': 'Suisse', 'belgium': 'Belgique',
  'netherlands': 'Pays-Bas', 'united kingdom': 'Royaume-Uni', 'uk': 'Royaume-Uni',
  'england': 'Royaume-Uni', 'russia': 'Russie', 'georgia': 'Géorgie',
  'armenia': 'Arménie', 'south africa': 'Afrique du Sud', 'kenya': 'Kenya',
  'tanzania': 'Tanzanie', 'mexico': 'Mexique', 'brazil': 'Brésil',
  'cuba': 'Cuba', 'dominican republic': 'République Dominicaine',
  'usa': 'États-Unis', 'united states': 'États-Unis', 'canada': 'Canada'
};

function normalizeCountryToFrench(country) {
  if (!country || typeof country !== 'string') return null;
  const key = stripAccents(country);
  if (COUNTRY_EN_TO_FR[key]) return COUNTRY_EN_TO_FR[key];
  for (const frName of Object.values(COUNTRY_EN_TO_FR)) {
    if (stripAccents(frName) === key) return frName;
  }
  return country.trim().charAt(0).toUpperCase() + country.trim().slice(1).toLowerCase();
}

function dedupeCountries(arr) {
  const seen = new Set();
  const out = [];
  for (const c of (arr || [])) {
    const fr = normalizeCountryToFrench(c);
    if (!fr) continue;
    const key = stripAccents(fr);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(fr);
  }
  return out;
}

// MAPPING ANGLAIS → FRANÇAIS POUR LES SERVICES
const SERVICE_EN_TO_FR = {
  'direct flight': 'Vol direct', 'flight': 'Vol', 'flights': 'Vols',
  'plane ticket': "Billet d'avion", 'plane tickets': "Billets d'avion",
  'round trip': 'Aller-retour', 'one way': 'Aller simple',
  'airport transfer': 'Transfert aéroport', 'airport transfers': 'Transferts aéroport',
  'transfer': 'Transfert', 'transfers': 'Transferts',
  'private transfer': 'Transfert privé', 'shared transfer': 'Transfert partagé',
  'hotel': 'Hôtel', 'hotels': 'Hôtels', 'accommodation': 'Hébergement',
  'breakfast': 'Petit déjeuner', 'breakfasts': 'Petits déjeuners',
  'half board': 'Demi-pension', 'full board': 'Pension complète',
  'all inclusive': 'Tout inclus', 'all-inclusive': 'Tout inclus',
  'guide': 'Guide', 'guided tour': 'Visite guidée', 'tour guide': 'Guide touristique',
  'excursion': 'Excursion', 'excursions': 'Excursions',
  'sightseeing': 'Visites touristiques', 'visit': 'Visite', 'visits': 'Visites',
  'lunch': 'Déjeuner', 'dinner': 'Dîner',
  'meal': 'Repas', 'meals': 'Repas',
  'drinks': 'Boissons', 'water': 'Eau',
  'visa': 'Visa', 'evisa': 'E-visa', 'e-visa': 'E-visa',
  'travel insurance': 'Assurance voyage', 'insurance': 'Assurance',
  'accompaniment': 'Accompagnement',
  'accompaniment during the stay': 'Accompagnement durant le séjour',
  'assistance': 'Assistance',
  'shopping': 'Shopping', 'beach': 'Plage', 'spa': 'Spa',
  'tips': 'Pourboires', 'gratuities': 'Pourboires',
  'optional': 'Optionnel', 'personal expenses': 'Dépenses personnelles'
};

function translateService(s) {
  if (typeof s !== 'string' || !s.trim()) return s;
  const original = s.trim();
  const key = stripAccents(original);
  if (SERVICE_EN_TO_FR[key]) return SERVICE_EN_TO_FR[key];
  return original;
}

function dedupeAndTranslateServices(arr) {
  if (!Array.isArray(arr)) return [];
  const seen = new Set();
  const out = [];
  for (const s of arr) {
    if (typeof s !== 'string' || !s.trim()) continue;
    const translated = translateService(s).trim();
    const key = stripAccents(translated);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(translated);
  }
  return out;
}

// ----------------------------------------------------------------------------
// PAYLOAD INITIAL VIDE (même structure que Format Text Result)
// ----------------------------------------------------------------------------
const final = {
  title: null,
  agency_id: 1,
  agency_name: null,
  countries: [],
  duration_nights: null,
  airline: null,
  description: null,
  itinerary: [],
  status: 'draft',
  photo_urls: [],
  is_global_pricing: false,
  global_pricing: null,
  lead_price: null,
  services: { included: [], excluded: [] },
  steps: [],
  departures: []
};

// ----------------------------------------------------------------------------
// MERGE INTELLIGENT (priorité au premier non-null)
// ----------------------------------------------------------------------------
const mergedSources = [];

for (const item of items) {
  const p = item?.payload;
  if (!p || !item._hasData) continue;

  mergedSources.push(item.source || item.extractionType);

  // Champs simples : on garde la première valeur non-null
  final.title = final.title ?? p.title ?? null;
  final.agency_id = final.agency_id ?? p.agency_id ?? 1;
  final.agency_name = final.agency_name ?? p.agency_name ?? null;
  final.duration_nights = final.duration_nights ?? p.duration_nights ?? null;
  final.airline = final.airline ?? p.airline ?? null;
  final.description = final.description ?? p.description ?? null;

  // Itinéraire : normalise chaque source en tableau, garde le plus riche
  if (p.itinerary) {
    const normalized = normalizeItinerary(p.itinerary);
    if (normalized.length > final.itinerary.length) {
      final.itinerary = normalized;
    }
  }

  // Photos : concaténation (image et PDF peuvent en apporter)
  if (Array.isArray(p.photo_urls) && p.photo_urls.length > 0) {
    final.photo_urls = uniqueStrings([...final.photo_urls, ...p.photo_urls]);
  }

  // Pays : concaténer (la dédup FR se fera après tous les merges)
  if (Array.isArray(p.countries)) {
    final.countries = [...final.countries, ...p.countries];
  }

  // Services : concaténer (dédup + traduction se feront après tous les merges)
  if (p.services?.included) {
    final.services.included = [...final.services.included, ...p.services.included];
  }
  if (p.services?.excluded) {
    final.services.excluded = [...final.services.excluded, ...p.services.excluded];
  }

  // Steps : on prend la liste la plus longue
  if (Array.isArray(p.steps) && p.steps.length > final.steps.length) {
    final.steps = p.steps;
  }

  // Departures : on prend la liste la plus longue
  if (Array.isArray(p.departures) && p.departures.length > final.departures.length) {
    final.departures = p.departures;
  }

  // Pricing : priorité au premier qui définit is_global_pricing
  if (final.is_global_pricing === false && p.is_global_pricing === true) {
    final.is_global_pricing = true;
    final.global_pricing = p.global_pricing;
  }
  final.lead_price = final.lead_price ?? p.lead_price ?? null;
}

// ----------------------------------------------------------------------------
// NORMALISATION FINALE FRANÇAIS + DÉDUP (post-merge)
// ----------------------------------------------------------------------------
final.countries = dedupeCountries(final.countries);
final.services.included = dedupeAndTranslateServices(final.services.included);
final.services.excluded = dedupeAndTranslateServices(final.services.excluded);

// Sécurité : si lead_price toujours null mais on a un global_pricing
if (final.lead_price === null && final.global_pricing !== null) {
  final.lead_price = final.global_pricing;
}

final.itinerary = normalizeItinerary(final.itinerary);

// ============================================================================
// GARDE-FOU FINAL : Séjours organisés et Omra / Hadj UNIQUEMENT
// ============================================================================
const textToCheck = [
  final.title || '',
  final.description || '',
  ...(final.countries || []),
  ...(final.services?.included || []),
  ...(final.steps?.map(s => s.city) || [])
].join(' ').toLowerCase();

// 1. Rejet formel des résidus de RDV Visa / démarches consulaires
const isVisaService = /\b(prise\s+de\s+rdv|rdv\s+visa|rendez[\s-]?vous\s+visa|rdv\s+disponible|dossier\s+visa|demande\s+de\s+visa|bls|tls|tlscontact|vfs|capago)\b/i.test(textToCheck);

if (isVisaService) {
  return []; // Stop immédiat
}

// 2. Vérification : Omra / Hadj OU Voyage Organisé
const isOmraHadj = /\b(omra|umrah|hadj|hajj|makkah|madinah|mecque|medine|médine|rawda)\b/i.test(textToCheck) ||
  (final.countries || []).some(c => /arabie\s+saoudite/i.test(c));

const hasStepsOrHotels = (final.steps || []).some(s => s.city || (s.hotels && s.hotels.length > 0));
const hasDuration = (final.duration_nights || 0) > 0;
const isOrganizedTrip = hasStepsOrHotels || hasDuration;

if (!isOmraHadj && !isOrganizedTrip) {
  return []; // Stop si ce n'est ni un séjour ni une Omra
}


// ============================================================================
// FILTRE QUALITÉ RENFORCÉ (Séjours organisés & Omra / Hadj stricts)
// ============================================================================

// 1. Rejet des offres incomplètes ou fantômes
if (!final.title || final.title === 'Offre sans titre' || (final.countries || []).length === 0) {
  return [];
}

// 2. Rejet des prix suspects ou trop bas (< 50 000 DA ou 0)
const price = final.lead_price ?? final.global_pricing ?? null;
if (price === null || price < 50000) {
  return [];
}

// 3. Rejet des durées trop courtes (billets secs ou nuitée unitaire B2B)
if ((final.duration_nights || 0) < 2) {
  return [];
}

// 4. Rejet des vols secs résiduels
const titleLower = (final.title || '').toLowerCase();
const isFlightTitle = /^(vols?|billets?)\b/i.test(titleLower);
const hasNoHotels = !(final.steps || []).some(s => (s.hotels || []).some(h => h.custom_hotel_name));
if (isFlightTitle && hasNoHotels) {
  return [];
}

// Note : Si vous voulez AUSSI rejeter les offres qui n'ont AUCUN prix visible,
// décommentez les 3 lignes suivantes :
// if (price === null || price === 0) {
//   return [];
// }

return [{
  json: {
    ...final,
    _merged_sources: mergedSources,
    _merge_count: mergedSources.length
  }
}];

return [{
  json: {
    ...final,
    _merged_sources: mergedSources,
    _merge_count: mergedSources.length
  }
}];

const parseResult = $input.first().json;
const detectData = $('Detect Content & Generate JobId').first().json;

const jobId = detectData.jobId || 'unknown';

// ============================================================
// normalizeItinerary : garantit toujours un tableau [{day,title,items}]
// Convertit l'ancien format {day_1,day_2} ET valide le nouveau
// ============================================================
function normalizeItinerary(raw) {
  if (!raw) return [];

  // Découpe une phrase en items logiques
  function splitIntoItems(text) {
    if (typeof text !== 'string') return [];
    const t = text.trim();
    if (!t) return [];
    // Découpe sur , ; / . / retours ligne, garde segments non vides
    const parts = t
      .split(/[\n•;]|(?:,\s)|(?:\.\s)|(?:\s\/\s)/)
      .map(s => s.replace(/^[\s\-–—*.]+|[\s\-–—*.]+$/g, '').trim())
      .filter(s => s.length > 1);
    return parts.length > 0 ? parts : [t];
  }

  // Titre court depuis le 1er segment
  function makeTitle(items, fallback) {
    const first = (items && items[0]) ? items[0] : fallback;
    if (!first) return 'Journée';
    let title = String(first).trim();
    if (title.length > 60) title = title.slice(0, 57).trim() + '...';
    return title;
  }

  // ── Déjà un tableau
  if (Array.isArray(raw)) {
    const out = [];
    raw.forEach((entry, idx) => {
      if (!entry) return;
      // Entrée déjà au bon format
      if (typeof entry === 'object' && !Array.isArray(entry)) {
        let items = [];
        if (Array.isArray(entry.items)) {
          items = entry.items.map(x => String(x).trim()).filter(Boolean);
        } else if (typeof entry.description === 'string') {
          items = splitIntoItems(entry.description);
        } else if (typeof entry.text === 'string') {
          items = splitIntoItems(entry.text);
        }
        const dayNum = Number.isFinite(entry.day) ? entry.day
          : (parseInt(entry.day, 10) || idx + 1);
        const title = (typeof entry.title === 'string' && entry.title.trim())
          ? entry.title.trim() : makeTitle(items, null);
        if (items.length === 0 && !title) return;
        out.push({ day: dayNum, title: title || makeTitle(items, 'Journée'), items: items.length ? items : [title] });
      } else if (typeof entry === 'string' && entry.trim()) {
        const items = splitIntoItems(entry);
        out.push({ day: idx + 1, title: makeTitle(items, null), items });
      }
    });
    return out.map((d, i) => ({ day: i + 1, title: d.title, items: d.items }));
  }

  // ── Objet ancien format {day_1, day_2} ou {jour 1, ...}
  if (typeof raw === 'object') {
    const entries = Object.entries(raw)
      .filter(([, v]) => typeof v === 'string' ? v.trim() : (v && typeof v === 'object'));
    // Trie par numéro de jour extrait de la clé
    entries.sort((a, b) => {
      const na = parseInt(String(a[0]).replace(/\D/g, ''), 10) || 0;
      const nb = parseInt(String(b[0]).replace(/\D/g, ''), 10) || 0;
      return na - nb;
    });
    const out = [];
    entries.forEach(([key, value], idx) => {
      const dayNum = parseInt(String(key).replace(/\D/g, ''), 10) || idx + 1;
      let items, title;
      if (typeof value === 'string') {
        items = splitIntoItems(value);
        title = makeTitle(items, null);
      } else if (value && typeof value === 'object') {
        items = Array.isArray(value.items)
          ? value.items.map(x => String(x).trim()).filter(Boolean)
          : splitIntoItems(value.description || value.text || '');
        title = (typeof value.title === 'string' && value.title.trim())
          ? value.title.trim() : makeTitle(items, null);
      } else {
        return;
      }
      if (items.length === 0) return;
      out.push({ day: dayNum, title, items });
    });
    return out.map((d, i) => ({ day: i + 1, title: d.title, items: d.items }));
  }

  return [];
}

function createEmptyTour() {
  return {
