function uniqueStrings(arr) {
  return [...new Set((arr || []).filter(v => typeof v === 'string' && v.trim() !== ''))];
}

function normalizeString(v) {
  return typeof v === 'string' && v.trim() !== '' ? v.trim() : null;
}

function normalizeNumber(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;

  if (typeof v === 'string') {
    const cleaned = v
      .trim()
      .replace(/\s+/g, '')
      .replace(/,/g, '.')
      .replace(/[^\d.-]/g, '');

    if (!cleaned || cleaned === '.' || cleaned === '-' || cleaned === '-.') return null;

    const num = Number(cleaned);
    return Number.isFinite(num) ? num : null;
  }

  return null;
}

function titleCaseCity(v) {
  const s = normalizeString(v);
  if (!s) return null;

  return s
    .toLowerCase()
    .split(/\s+/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

function titleCase(v) {
  const s = normalizeString(v);
  if (!s) return null;
  return s
    .toLowerCase()
    .split(/\s+/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function cleanAgencyName(v) {
  const s = normalizeString(v);
  if (!s) return null;
  return s
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/^[A-Z]\s+/i, '')
    .trim();
}

function extractAgencyName(text) {
  if (!text) return null;
  const normalized = text
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const patterns = [
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+TRAVEL)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+TOURS?)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+VOYAGES?)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+AGENCY)\b/i,
    /\b(AGENCE\s+[A-Z][A-Z0-9&.' -]{1,40})\b/i
  ];
  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    if (match) return cleanAgencyName(titleCase(match[1]));
  }
  return null;
}


function extractJsonString(raw) {
  if (!raw || typeof raw !== 'string') return null;

  let text = raw.trim();

  text = text.replace(/^```json\s*/i, '');
  text = text.replace(/^```\s*/i, '');
  text = text.replace(/\s*```$/i, '').trim();

  if (text.startsWith('{') && text.endsWith('}')) {
    return text;
  }

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return text.slice(firstBrace, lastBrace + 1);
  }

  return null;
}

function extractTextCandidates(value) {
  const results = [];

  function walk(node) {
    if (!node) return;

    if (typeof node === 'string') {
      results.push(node);
      return;
    }

    if (Array.isArray(node)) {
      for (const item of node) walk(item);
      return;
    }

    if (typeof node === 'object') {
      if (typeof node.text === 'string') results.push(node.text);
      if (typeof node.md === 'string') results.push(node.md);
      if (typeof node.markdown === 'string') results.push(node.markdown);
      if (typeof node.value === 'string') results.push(node.value);

      if (Array.isArray(node.parts)) {
        for (const part of node.parts) {
          if (typeof part?.text === 'string') results.push(part.text);
        }
      }

      if (node.content) walk(node.content);
      if (node.output) walk(node.output);
      if (node.response) walk(node.response);
      if (node.message) walk(node.message);
      if (node.pages) walk(node.pages);
      if (node.items) walk(node.items);
    }
  }

  walk(value);
  return results.filter(Boolean);
}

function normalizeHotelPricing(pricing) {
  return {
    dbl: normalizeNumber(pricing?.dbl ?? pricing?.double),
    tpl: normalizeNumber(pricing?.tpl ?? pricing?.triple),
    sgl: normalizeNumber(pricing?.sgl ?? pricing?.single),
    inf: normalizeNumber(pricing?.inf ?? pricing?.infant),
    chd_2_6: normalizeNumber(pricing?.chd_2_6 ?? pricing?.child_2_6),
    chd_5_11: normalizeNumber(pricing?.chd_5_11 ?? pricing?.child_5_11)
  };
}

function hasAnyHotelPrice(pricing) {
  if (!pricing || typeof pricing !== 'object') return false;
  return Object.values(pricing).some(v => v !== null);
}

function computeLeadPriceFromHotelPricing(pricing) {
  if (!pricing || typeof pricing !== 'object') return null;

  // Cheapest realistic adult price only.
  // Do not use child / infant prices for lead_price unless no adult price exists.
  const adultPrices = [
    normalizeNumber(pricing.tpl),
    normalizeNumber(pricing.dbl),
    normalizeNumber(pricing.sgl)
  ].filter(v => v !== null);

  if (adultPrices.length > 0) {
    return Math.min(...adultPrices);
  }

  return null;
}

function normalizeGlobalPricingAsNumber(value) {
  if (value === null || value === undefined) return null;

  if (typeof value === 'number' || typeof value === 'string') {
    return normalizeNumber(value);
  }

  // If the AI still returns old object format, extract only if there is exactly one value.
  if (typeof value === 'object' && !Array.isArray(value)) {
    const values = Object.values(value)
      .map(v => normalizeNumber(v))
      .filter(v => v !== null);

    if (values.length === 1) return values[0];
  }

  return null;
}

function extractPricesFromObject(obj) {
  const prices = [];

  function walk(node, key = '') {
    if (node === null || node === undefined) return;

    if (typeof node === 'number' && Number.isFinite(node)) {
      prices.push({
        key,
        value: node
      });
      return;
    }

    if (typeof node === 'string') {
      const n = normalizeNumber(node);
      if (n !== null && /\d/.test(node)) {
        prices.push({
          key,
          value: n
        });
      }
      return;
    }

    if (Array.isArray(node)) {
      for (const item of node) walk(item, key);
      return;
    }

    if (typeof node === 'object') {
      for (const [k, v] of Object.entries(node)) {
        walk(v, k);
      }
    }
  }

  walk(obj);
  return prices;
}

function isRoomPricingKey(key) {
  const k = String(key || '').toLowerCase();

  return [
    'dbl',
    'double',
    'tpl',
    'triple',
    'sgl',
    'single',
    'inf',
    'infant',
    'chd_2_6',
    'child_2_6',
    'chd_5_11',
    'child_5_11'
  ].includes(k);
}

function getCheapestAdultHotelPrice(steps) {
  const candidates = [];

  for (const step of steps || []) {
    for (const hotel of step.hotels || []) {
      const price = computeLeadPriceFromHotelPricing(hotel.pricing);
      if (price !== null) candidates.push(price);
    }
  }

  return candidates.length > 0 ? Math.min(...candidates) : null;
}

function dedupeDepartures(departures) {
  const seen = new Set();

  return (departures || [])
    .filter(dep =>
      dep.departure_city !== null ||
      dep.stock !== null ||
      dep.flight_departure_time !== null ||
      dep.flight_arrival_time !== null ||
      dep.return_flight_departure_time !== null ||
      dep.return_flight_arrival_time !== null
    )
    .filter(dep => {
      const key = [
        dep.departure_city,
        dep.flight_departure_time,
        dep.return_flight_departure_time
      ].join('|');

      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

