// ============================================================
// normalizeItinerary : garantit toujours un tableau [{day,title,items}]
// Convertit l'ancien format {day_1,day_2} ET valide le nouveau
// ============================================================
function normalizeItinerary(raw) {
  if (!raw) return [];

  // Découpe une phrase en items logiques
  function splitIntoItems(text) {
    if (typeof text !== 'string') return [];
    const t = text.trim();
    if (!t) return [];
    // Découpe sur , ; / . / retours ligne, garde segments non vides
    const parts = t
      .split(/[\n•;]|(?:,\s)|(?:\.\s)|(?:\s\/\s)/)
      .map(s => s.replace(/^[\s\-–—*.]+|[\s\-–—*.]+$/g, '').trim())
      .filter(s => s.length > 1);
    return parts.length > 0 ? parts : [t];
  }

  // Titre court depuis le 1er segment
  function makeTitle(items, fallback) {
    const first = (items && items[0]) ? items[0] : fallback;
    if (!first) return 'Journée';
    let title = String(first).trim();
    if (title.length > 60) title = title.slice(0, 57).trim() + '...';
    return title;
  }

  // ── Déjà un tableau
  if (Array.isArray(raw)) {
    const out = [];
    raw.forEach((entry, idx) => {
      if (!entry) return;
      // Entrée déjà au bon format
      if (typeof entry === 'object' && !Array.isArray(entry)) {
        let items = [];
        if (Array.isArray(entry.items)) {
          items = entry.items.map(x => String(x).trim()).filter(Boolean);
        } else if (typeof entry.description === 'string') {
          items = splitIntoItems(entry.description);
        } else if (typeof entry.text === 'string') {
          items = splitIntoItems(entry.text);
        }
        const dayNum = Number.isFinite(entry.day) ? entry.day
          : (parseInt(entry.day, 10) || idx + 1);
        const title = (typeof entry.title === 'string' && entry.title.trim())
          ? entry.title.trim() : makeTitle(items, null);
        if (items.length === 0 && !title) return;
        out.push({ day: dayNum, title: title || makeTitle(items, 'Journée'), items: items.length ? items : [title] });
      } else if (typeof entry === 'string' && entry.trim()) {
        const items = splitIntoItems(entry);
        out.push({ day: idx + 1, title: makeTitle(items, null), items });
      }
    });
    return out.map((d, i) => ({ day: i + 1, title: d.title, items: d.items }));
  }

  // ── Objet ancien format {day_1, day_2} ou {jour 1, ...}
  if (typeof raw === 'object') {
    const entries = Object.entries(raw)
      .filter(([, v]) => typeof v === 'string' ? v.trim() : (v && typeof v === 'object'));
    // Trie par numéro de jour extrait de la clé
    entries.sort((a, b) => {
      const na = parseInt(String(a[0]).replace(/\D/g, ''), 10) || 0;
      const nb = parseInt(String(b[0]).replace(/\D/g, ''), 10) || 0;
      return na - nb;
    });
    const out = [];
    entries.forEach(([key, value], idx) => {
      const dayNum = parseInt(String(key).replace(/\D/g, ''), 10) || idx + 1;
      let items, title;
      if (typeof value === 'string') {
        items = splitIntoItems(value);
        title = makeTitle(items, null);
      } else if (value && typeof value === 'object') {
        items = Array.isArray(value.items)
          ? value.items.map(x => String(x).trim()).filter(Boolean)
          : splitIntoItems(value.description || value.text || '');
        title = (typeof value.title === 'string' && value.title.trim())
          ? value.title.trim() : makeTitle(items, null);
      } else {
        return;
      }
      if (items.length === 0) return;
      out.push({ day: dayNum, title, items });
    });
    return out.map((d, i) => ({ day: i + 1, title: d.title, items: d.items }));
  }

  return [];
}

