    .filter(step => step.city !== null || step.hotels.length > 0);
}

payload.steps = payload.steps
  .sort((a, b) => (a.step_order ?? 9999) - (b.step_order ?? 9999))
  .map((step, index) => ({
    ...step,
    step_order: index + 1
  }));

// Duration from steps
const stepDurationValues = payload.steps
  .map(step => normalizeNumber(step.duration_nights))
  .filter(v => v !== null);

if (payload.steps.length > 0 && stepDurationValues.length === payload.steps.length) {
  payload.duration_nights = stepDurationValues.reduce((sum, v) => sum + v, 0);
}

// Departures - accepte plusieurs formats de date :
//   - flight_departure_time / return_flight_departure_time (format complet ISO)
//   - departure_date / return_date (format simple YYYY-MM-DD)
//   - date (alias court de departure_date)
function normalizeDateToIso(value) {
  const s = normalizeString(value);
  if (!s) return null;
  // Si déjà en ISO avec heure
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) return s;
  // Si format YYYY-MM-DD simple → ajouter T00:00:00Z
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return `${s}T00:00:00Z`;
  // Si format DD/MM/YYYY ou DD-MM-YYYY
  const m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (m) {
    let [_, dd, mm, yyyy] = m;
    if (yyyy.length === 2) yyyy = '20' + yyyy;
    return `${yyyy}-${mm.padStart(2, '0')}-${dd.padStart(2, '0')}T00:00:00Z`;
  }
  // Try "10 mai 2026" or "10 mai" (current year fallback)
  const _frMonths = {janvier:'01',fevrier:'02','février':'02',mars:'03',avril:'04',mai:'05',juin:'06',juillet:'07',aout:'08','août':'08',septembre:'09',octobre:'10',novembre:'11',decembre:'12','décembre':'12'};
  const _fr = s.toLowerCase().match(/^(\d{1,2})\s+(\S+)(?:\s+(\d{2,4}))?$/);
  if (_fr && _frMonths[_fr[2]]) {
    const dd = _fr[1].padStart(2, '0');
    const mm = _frMonths[_fr[2]];
    let yyyy = _fr[3] || String(new Date().getFullYear());
    if (yyyy.length === 2) yyyy = '20' + yyyy;
    return `${yyyy}-${mm}-${dd}T00:00:00Z`;
  }
  // Sinon retourner tel quel (LlamaParse peut envoyer des choses comme "10 mai 2026")
  return s;
}

if (Array.isArray(parsed.departures)) {
  payload.departures = parsed.departures
    .map(dep => {
      const explicitDepartureCity = normalizeString(dep.departure_city);
      const stock = normalizeNumber(dep.stock);

      // Accept multiple date field names (IA inconsistency)
      const flightDepartureTime = normalizeDateToIso(
        dep.flight_departure_time ||
        dep.departure_date ||
        dep.date ||
        dep.departure
      );
      const flightArrivalTime = normalizeDateToIso(
        dep.flight_arrival_time ||
        dep.arrival_date ||
        dep.arrival
      );
      const returnFlightDepartureTime = normalizeDateToIso(
        dep.return_flight_departure_time ||
        dep.return_date ||
        dep.return
      );
      const returnFlightArrivalTime = normalizeDateToIso(
        dep.return_flight_arrival_time ||
        dep.return_arrival_date ||
        dep.return_arrival
      );

      const hasMeaningfulData =
        explicitDepartureCity !== null ||
        stock !== null ||
        flightDepartureTime !== null ||
        flightArrivalTime !== null ||
        returnFlightDepartureTime !== null ||
        returnFlightArrivalTime !== null;

      if (!hasMeaningfulData) return null;

      return {
        departure_city: explicitDepartureCity || 'Alger',
        stock,
        flight_departure_time: flightDepartureTime,
        flight_arrival_time: flightArrivalTime,
        return_flight_departure_time: returnFlightDepartureTime,
        return_flight_arrival_time: returnFlightArrivalTime
      };
    })
    .filter(Boolean);
}

payload.departures = dedupeDepartures(payload.departures);

// ------------------------------
// PRICING BUSINESS LOGIC
// ------------------------------

const parsedLeadPrice = normalizeNumber(parsed.lead_price);
const parsedGlobalPricingNumber = normalizeGlobalPricingAsNumber(parsed.global_pricing);

const hasHotelPricing = payload.steps.some(step =>
  step.hotels.some(hotel => hasAnyHotelPrice(hotel.pricing))
);

const allParsedPrices = extractPricesFromObject({
  global_pricing: parsed.global_pricing,
  steps: parsed.steps,
  lead_price: parsed.lead_price
});

// Count meaningful prices.
// If the only price is lead_price and no hotel pricing exists, it is a single global price.
// Filter to keep only actual price keys (skip agency_id, step_order, duration_nights, stock, etc.)
const PRICE_KEYS_ALLOWED = new Set([
  'dbl', 'double', 'tpl', 'triple', 'sgl', 'single',
  'inf', 'infant', 'chd_2_6', 'child_2_6', 'chd_5_11', 'child_5_11',
  'global_pricing', 'lead_price', 'price', 'tarif',
  'pricing'  // value of pricing key itself when it's a number
]);

const realPriceEntries = allParsedPrices.filter(p => {
  const k = String(p.key || '').toLowerCase();
  return PRICE_KEYS_ALLOWED.has(k);
});

const numericPriceValues = realPriceEntries.map(p => p.value);
const uniquePriceValues = [...new Set(numericPriceValues)];

const hotelRoomPriceValues = [];

for (const step of payload.steps) {
  for (const hotel of step.hotels) {
    for (const [key, value] of Object.entries(hotel.pricing || {})) {
      if (isRoomPricingKey(key) && value !== null) {
        hotelRoomPriceValues.push(value);
      }
    }
  }
}

const uniqueHotelRoomPrices = [...new Set(hotelRoomPriceValues)];

const cheapestHotelAdultPrice = getCheapestAdultHotelPrice(payload.steps);

// =====================================================================
// SAFETY NET pour global_pricing :
// Si TOUS les prix trouvés dans l'offre (y compris ceux dans hotel.pricing)
// sont identiques, c'est en fait UN SEUL prix global, même si l'IA l'a
// par erreur mis dans pricing.dbl/tpl/sgl.
//
// On considère que c'est un global_pricing si :
//   - Au moins UN prix est visible quelque part
//   - ET tous les prix uniques de l'offre = 1 seule valeur
// Dans ce cas : on vide hotel.pricing et on met le prix dans global_pricing.
// =====================================================================

const allUniquePricesInOffer = [...new Set([
  ...uniquePriceValues,
  ...uniqueHotelRoomPrices
])];

const hasOnlyOneVisiblePrice = allUniquePricesInOffer.length === 1;

// Case 1:
// ONE single price in the whole offer (anywhere: global_pricing, lead_price,
// or hotel.pricing.dbl/tpl/sgl/...). All these prices are identical.
// → It's a global_pricing. Clear hotel.pricing and set global_pricing.
if (hasOnlyOneVisiblePrice) {
  const onlyPrice = allUniquePricesInOffer[0];

  payload.is_global_pricing = true;
  payload.global_pricing = onlyPrice;
  payload.lead_price = onlyPrice;

  // SAFETY: clear all hotel.pricing values to null
  // (the price was a global one, not a per-room one)
  for (const step of payload.steps) {
    for (const hotel of step.hotels) {
      hotel.pricing = normalizeHotelPricing({});
    }
  }
}

// Case 2:
// AI explicitly returned global_pricing number and no hotel pricing exists.
else if (
  parsed.is_global_pricing === true &&
  parsedGlobalPricingNumber !== null &&
  !hasHotelPricing
) {
  payload.is_global_pricing = true;
  payload.global_pricing = parsedGlobalPricingNumber;
  payload.lead_price = parsedLeadPrice ?? parsedGlobalPricingNumber;
}

// Case 3:
// Multiple prices or hotel/room prices exist.
// global_pricing must be null.
else {
  payload.is_global_pricing = false;
  payload.global_pricing = null;

  const leadCandidates = [
    parsedLeadPrice,
    cheapestHotelAdultPrice
  ].filter(v => v !== null);

  payload.lead_price = leadCandidates.length > 0
    ? Math.min(...leadCandidates)
    : null;
}

// Final safety:
// Never copy lead_price into hotel pricing.
// Hotel pricing remains only what was explicitly parsed under hotel pricing.
for (const step of payload.steps) {
  for (const hotel of step.hotels) {
    hotel.pricing = normalizeHotelPricing(hotel.pricing);
  }
}

return [{
  json: {
    extractionType: 'image',
    _hasData: true,
    source: 'image',
    jobId,
    debug_used_candidate_preview: usedRawCandidate ? usedRawCandidate.slice(0, 300) : null,
    payload
  }
}];

// ============================================================================
// NŒUD : Detect Noise v4 (Spécialisé : Séjours Organisés & Omra / Hadj)
// PLACE : Après "Detect Content & Generate JobId", AVANT "IF Valid Offer"
// ============================================================================

const root = $json;
const payload = root.originalPayload || root;
const _binaryIn = $input.first().binary || {};

// ============================================================================
// 1. VÉRIFICATION ANTI-DOUBLON PERSISTANTE (Supabase / PostgreSQL)
// ============================================================================
const _contentHash = root._content_hash;
const forceUpload = !!(root.body?.force_upload || root.originalBody?.force_upload || root.force_upload);

if (_contentHash && !forceUpload) {
  try {
    const sKey = (typeof $env !== 'undefined' ? $env.SUPABASE_SERVICE_ROLE_KEY : null) || (typeof process !== 'undefined' ? process.env?.SUPABASE_SERVICE_ROLE_KEY : '') || '';
    const http = require('http');

    const existing = await new Promise((resolve) => {
      const options = {
        hostname: 'supabase-kong',
        port: 8000,
        path: `/rest/v1/ingestion_hashes?content_hash=eq.${_contentHash}&select=id,tour_id`,
        method: 'GET',
        headers: {
          'apikey': sKey,
          'Authorization': `Bearer ${sKey}`
        },
        timeout: 3000
      };
      const req = http.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => { data += chunk; });
        res.on('end', () => {
          try {
            if (res.statusCode >= 200 && res.statusCode < 300) {
              const json = JSON.parse(data);
              resolve(Array.isArray(json) && json.length > 0 ? json : null);
            } else {
              resolve(null);
            }
          } catch (e) {
            resolve(null);
          }
        });
      });
      req.on('error', () => resolve(null));
      req.on('timeout', () => { req.destroy(); resolve(null); });
      req.end();
    });

    if (existing && existing.length > 0) {
      return [{
        json: {
          ...root,
          classification: 'duplicate_already_ingested',
          is_valid_offer: false,
          _debug_reason: `duplicate_hash_found_tour_${existing[0].tour_id}`,
          _existing_tour_id: existing[0].tour_id
        }
      }];
    }
  } catch (err) {
    // Si échec inattendu, on n'interrompt pas le flux
  }
}

// ============================================================================
// 2. FAST PATH : Uploads manuels depuis le front admin (si non-doublon)
// ============================================================================
if (root.directUpload === true) {
  let _cls = 'valid_image_offer';
  if (root.hasPdf) _cls = 'valid_pdf_offer';
  else if (!root.hasImage && root.hasText) _cls = 'valid_travel_offer';
  return [{
    json: {
      ...root,
      classification: _cls,
      is_valid_offer: true,
      _debug_reason: 'direct_upload_bypass'
    },
    binary: _binaryIn
  }];
}

// 1. EXTRACTION DU MESSAGE
// ----------------------------------------------------------------------------
let msg =
  payload.body?.data?.message ||
  payload.body?.data?.messages?.[0]?.message ||
  payload.data?.message ||
  payload.message ||
  {};

if (msg.ephemeralMessage?.message) msg = msg.ephemeralMessage.message;
if (msg.viewOnceMessage?.message) msg = msg.viewOnceMessage.message;
if (msg.viewOnceMessageV2?.message) msg = msg.viewOnceMessageV2.message;
if (msg.documentWithCaptionMessage?.message) {
  msg = { ...msg, ...msg.documentWithCaptionMessage.message };
}

// ----------------------------------------------------------------------------
// 2. DÉTECTION DES MÉDIAS
// ----------------------------------------------------------------------------
const imageMessage = msg.imageMessage || null;
const documentMessage = msg.documentMessage || null;
const audioMessage = msg.audioMessage || null;
const stickerMessage = msg.stickerMessage || null;
const videoMessage = msg.videoMessage || null;

const mime = String(
  imageMessage?.mimetype ||
  documentMessage?.mimetype ||
  payload.body?.data?.mimetype ||
  payload.mimetype ||
  payload.mimeType ||
  ''
).toLowerCase();

const fileName = String(
  documentMessage?.fileName ||
  documentMessage?.title ||
  payload.body?.data?.fileName ||
  payload.body?.data?.title ||
  payload.fileName ||
  payload.filename ||
  payload.title ||
  ''
).trim().toLowerCase();

const isImage = !!imageMessage || mime.startsWith('image/');
let isPdf = !!documentMessage || mime === 'application/pdf' || fileName.endsWith('.pdf');
const isAudio = !!audioMessage || mime.startsWith('audio/');
const isSticker = !!stickerMessage;
const isVideo = !!videoMessage || mime.startsWith('video/');

// ----------------------------------------------------------------------------
// 3. EXTRACTION DU TEXTE
// ----------------------------------------------------------------------------
const raw = String(
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  imageMessage?.caption ||
  documentMessage?.caption ||
  fileName ||
  payload.text ||
  (typeof payload.message === 'string' ? payload.message : '') ||
  ''
).trim();

if (!isPdf && raw.toLowerCase().includes('.pdf')) {
  isPdf = true;
}

const hasText = raw.length > 0;

const normalized = raw
  .toLowerCase()
  .replace(/\n/g, ' ')
  .replace(/\s+/g, ' ')
  .replace(/[^\p{L}\p{N}\s€$.,:/+\-]/gu, ' ')
  .trim();

// ----------------------------------------------------------------------------
// 4. AUDIO / STICKER / VIDÉO → REJET
// ----------------------------------------------------------------------------
if (isAudio || isSticker || isVideo) {
  return [{
    json: {
      ...$json,
      classification: 'noise_unsupported_media',
      is_valid_offer: false,
      _debug_reason: isAudio ? 'audio_message' : isSticker ? 'sticker_message' : 'video_message'
    }
  }];
}

// ============================================================================
// 5. CATÉGORIES DE BRUIT — DÉTECTION STRICTE
// ============================================================================

// ----------------------------------------------------------------------------
// 5.A VISA / RDV CONSULAIRES (REJET PRIORITAIRE)
// ----------------------------------------------------------------------------
// Détection des centres et prestataires de visa
const visaCenters = /\b(bls|tls|tlscontact|vfs|vfs\s*global|capago)\b/i;

// Expressions spécifiques aux RDV de visa
const visaRdvPatterns = [
  /\brdv\s+visa\b/i,
  /\brendez[\s-]?vous\s+visa\b/i,
  /\bdemande\s+de\s+visa\b/i,
  /\bdossier\s+visa\b/i,
  /\bproc[eé]dure\s+visa\b/i,
  /\bprise\s+de\s+rdv\b/i,
  /\bprise\s+de\s+rendez[\s-]?vous\b/i,
  /\bdisponible\s+rdv\b/i,
  /\brdv\s+disponible\b/i,
  /\brendez[\s-]?vous\s+disponible\b/i,
  /\brdv\s+(espagne|france|italie|allemagne|portugal|belgique|schengen)\b/i,
  /\brendez[\s-]?vous\s+(espagne|france|italie|allemagne|portugal|belgique|schengen)\b/i,
  /\bregroupement\s+familial\b/i,
  /\brdv\s+[\w\s]{0,20}(a|à)\s+domicile\b/i
];

const hasVisaRdvPattern = visaRdvPatterns.some(rx => rx.test(normalized));
const hasVisaCenter = visaCenters.test(normalized);

// Si le nom du fichier PDF contient un indicateur de visa
const isVisaFileName = /(visa|bls|tls|vfs|rendezvous|rdv)/i.test(fileName);

const isVisaOffer = hasVisaRdvPattern || hasVisaCenter || isVisaFileName;

// ----------------------------------------------------------------------------
// 5.B DEMANDES / RECHERCHES B2B (REJET)
// ----------------------------------------------------------------------------
const requestPatterns = [
  /\bon\s+cherche\b/i,
  /\bont\s+cherche\b/i,
  /\bje\s+cherche\b/i,
  /\bnous\s+cherchons\b/i,
  /\bcherche\s+(d[eé]part|vol|billet|h[oô]tel|s[eé]jour|programme|partenaire)/i,
  /\bje\s+veux\b/i,
  /\bje\s+voudrais\b/i,
  /\bj'?ai\s+besoin\b/i,
  /\bbesoin\s+(de|d'|d\s)/i,
  /\bqui\s+a\b/i,
  /\bsvp\b/i,
  /\bs'?il\s+vous\s+pla[iî]t\b/i
];

const isRequest = requestPatterns.some(rx => rx.test(normalized));

// ----------------------------------------------------------------------------
// 5.C BILLET SEC / TRANSPORT SEUL (REJET)
// ----------------------------------------------------------------------------
const flightOnlyKeywords = [
  /\bbillet\s+d['e]?\s*avion\b/i,
  /\bbillets?\s+disponibles?\b/i,
  /\bvente\s+billet\b/i,
  /\bbillet\s+sec\b/i,
  /\bvol\s+sec\b/i
];

const hasFlightOnlyKeyword = flightOnlyKeywords.some(rx => rx.test(normalized));

// Mots-clés indiquant la présence d'un séjour / hébergement
const stayKeywords = [
  'hotel', 'hôtel', 'hôtels', 'hotels', 'hébergement', 'hebergement',
  'séjour', 'sejour', 'séjours', 'sejours', 'resort',
  'pension', 'demi-pension', 'all inclusive', 'all-inclusive', 'pension complète',
  'circuit', 'package', 'forfait', 'nuits', 'nuitées', 'nuitees',
  'chambre', 'chambres', 'programme', 'itinéraire', 'itineraire',
  'excursion', 'excursions'
];
const hasStayKeyword = stayKeywords.some(k => normalized.includes(k));

// Routes de vol seules (ex: ALG-IST-ALG) sans hébergement
const routePattern = /\b[a-z]{2,4}\s*[-–]\s*[a-z]{2,4}(\s*[-–]\s*[a-z]{2,4})?\b/i;
const isFlightOnly = (hasFlightOnlyKeyword || routePattern.test(normalized)) && !hasStayKeyword;

// Bus sec
const busOnlyPatterns = [/\bpar\s+bus\b/i, /\ben\s+bus\b/i, /\bd[eé]part\s+bus\b/i];
const isBusOnly = busOnlyPatterns.some(rx => rx.test(normalized)) && !hasStayKeyword;

// Salutations pures / messages courts
const noiseOnlyPhrases = [
  /^(bonjour|bonsoir|salut|coucou|hello|hi|hey|salem|salam)[\s!?.]*$/i,
  /^(ça va|ca va|ca va\?|ça va\?|cv|cv\?)[\s!?.]*$/i,
  /^(merci|merci beaucoup|ok|d'accord|daccord|oui|non|inchallah|inshallah)[\s!?.]*$/i,
  /^(appelle?[ -]?moi|rappel(le|er) moi|tu peux m'appeler)[\s!?.]*$/i
];
const isNoisePureGreeting = noiseOnlyPhrases.some(rx => rx.test(raw));
const isTrivialShort = raw.length > 0 && raw.length < 5 && !/\d/.test(raw);

// ============================================================================
// 6. DÉTECTION QUALIFIÉE : OMRA / HADJ ou SÉJOUR ORGANISÉ
// ============================================================================

// --- 6.A Univers OMRA / HADJ ---
const omraHadjKeywords = [
  'omra', 'umrah', 'omrah', 'hadj', 'hajj', 'hadji',
  'makkah', 'mecque', 'madinah', 'medine', 'médine',
  'rawda', 'haram', 'kaaba', 'saoudite', 'saudi'
];
const isOmraHadj = omraHadjKeywords.some(k => normalized.includes(k));

// --- 6.B Univers SÉJOUR VOYAGE ORGANISÉ ---
// Exige à la fois une notion d'hébergement ET une notion de formule/séjour
const hasAccommodation = /(hotel|hôtel|resort|chambre|pension|hebergement|hébergement)/i.test(normalized);
const hasTripStructure = /(nuit|nuits|jour|jours|sejour|séjour|circuit|programme|excursion|visite|inclus)/i.test(normalized);
const isOrganizedTrip = hasAccommodation && hasTripStructure;

// Prix et dates
const hasPrice = /(\d{2,6}\s?(da|dzd|eur|€|\$))/i.test(normalized);
const hasDate = /\b(\d{1,2}[\/\-]\d{1,2}([\/\-]\d{2,4})?)\b/i.test(normalized);

// ============================================================================
// 7. APPLICATION DES RÈGLES
// ============================================================================

// -- 7.1 VISA / RDV → REJET IMMÉDIAT --
if (isVisaOffer) {
  return [{
    json: {
      ...$json,
      classification: 'excluded_visa_offer',
      is_valid_offer: false,
      _debug_reason: 'visa_appointment_or_service_detected',
      _debug_raw: raw
    }
  }];
}

// -- 7.2 DEMANDE / RECHERCHE → REJET --
if (isRequest) {
  return [{
    json: {
      ...$json,
      classification: 'excluded_request_offer',
      is_valid_offer: false,
      _debug_reason: 'b2b_request_or_search',
      _debug_raw: raw
    }
  }];
}

// -- 7.3 BILLETS SECS / BUS SEC → REJET --
if (isFlightOnly || isBusOnly) {
  return [{
    json: {
      ...$json,
      classification: isFlightOnly ? 'excluded_flight_only' : 'excluded_bus_only',
      is_valid_offer: false,
      _debug_reason: 'transport_only_no_stay',
      _debug_raw: raw
    }
  }];
}

// -- 7.4 BRUIT PUR / SALUTATIONS → REJET --
if (isNoisePureGreeting || isTrivialShort) {
  return [{
    json: {
      ...$json,
      classification: 'noise',
      is_valid_offer: false,
      _debug_reason: isNoisePureGreeting ? 'pure_greeting' : 'trivial_short',
      _debug_raw: raw
    }
  }];
}

// -- 7.5 IMAGE OU PDF SEUL (SANS TEXTE) --
// On autorise l'envoi à l'OCR / Gemini pour extraction, mais en signalant le besoin de filtre
if ((isImage || isPdf) && !hasText) {
  return [{
    json: {
      ...$json,
      classification: isImage ? 'valid_image_offer' : 'valid_pdf_offer',
      is_valid_offer: true,
      _debug_reason: isImage ? 'image_only_forward_to_ocr' : 'pdf_only_forward_to_ocr'
    }
  }];
}

// -- 7.6 IMAGE OU PDF AVEC TEXTE / CAPTION --
if ((isImage || isPdf) && hasText) {
  // Si la légende est du pur bruit
  const wordCount = normalized.split(/\s+/).filter(w => w.length > 0).length;
  if (wordCount <= 4 && (isNoisePureGreeting || isTrivialShort)) {
    return [{
      json: {
        ...$json,
        classification: 'noise_caption_with_media',
        is_valid_offer: false,
        _debug_reason: 'caption_is_pure_noise'
      }
    }];
  }

  // Si la légende confirme Omra/Hadj ou Voyage Organisé, ou si c'est un média avec texte descriptif
  return [{
    json: {
      ...$json,
      classification: isImage ? 'valid_image_offer' : 'valid_pdf_offer',
      is_valid_offer: true,
      _target_category: isOmraHadj ? 'omra_hadj' : (isOrganizedTrip ? 'organized_trip' : 'media_check'),
      _debug_reason: 'media_with_valid_caption'
    }
  }];
}

// -- 7.7 TEXTE SEUL : FILTRE STRICT SÉJOUR ORGANISÉ OU OMRA / HADJ --
if (!isImage && !isPdf && hasText) {
  // RÈGLE D'OR : Pour du texte seul, il FAUT soit être une Omra/Hadj, soit un Séjour Organisé
  const isValidTarget = (isOmraHadj || isOrganizedTrip) && (hasPrice || hasDate || normalized.length >= 40);

  if (isValidTarget) {
    return [{
      json: {
        ...$json,
        classification: 'valid_travel_offer',
        is_valid_offer: true,
        category: isOmraHadj ? 'omra_hadj' : 'organized_trip',
        _debug_reason: isOmraHadj ? 'target_omra_hadj_text' : 'target_organized_trip_text',
        _debug_raw: raw
      }
    }];
  }

  // Si le texte ne correspond ni à Omra/Hadj ni à un séjour organisé : REJET
  return [{
    json: {
      ...$json,
      classification: 'noise_unrelated_text',
      is_valid_offer: false,
      _debug_reason: 'not_organized_trip_nor_omra_hadj',
      _debug_raw: raw
    }
  }];
}

// Cas par défaut : REJET
return [{
  json: {
    ...$json,
    classification: 'noise',
    is_valid_offer: false,
    _debug_reason: 'unclassified_dropped',
    _debug_raw: raw
  }
}];

// ============================================================================
// NŒUD : Build Storage Path
// PLACE : Après "List Storage Folder", AVANT les uploads et le SQL
// 
// Les slugs (country, agency) ont déjà été calculés par "Compute Slugs"
// donc on les lit directement depuis $json._slugs (pas de recalcul).
// ============================================================================


const finalPayload = $('Compute Slugs').first().json;

// On récupère les infos de présence des médias depuis Detect Content
const detectData = $('Detect Content & Generate JobId').first().json;
const hasText = detectData.hasText === true;
const hasImage = detectData.hasImage === true;
const hasPdf = detectData.hasPdf === true;
const rawText = detectData.text || null;
const jobId = detectData.jobId || `job_${Date.now()}_unknown`;

// ----------------------------------------------------------------------------
// 1. SLUGS (déjà calculés par Compute Slugs)
// ----------------------------------------------------------------------------
const slugs = finalPayload._slugs || {};
const countrySlug = slugs.country || 'unknown-country';
const agencySlug = slugs.agency || 'unknown-agency';
const countryRaw = slugs.country_raw || null;
const agencyRaw = slugs.agency_raw || null;

// ----------------------------------------------------------------------------
// 2. CALCUL DU PROCHAIN PUBLICATION_ID
// ----------------------------------------------------------------------------
const listResult = $input.first().json;

// L'API Supabase peut renvoyer dans différents formats selon la config n8n
let folders = [];
if (Array.isArray(listResult)) {
  folders = listResult;
} else if (Array.isArray(listResult?.body)) {
  folders = listResult.body;
} else if (Array.isArray(listResult?.data)) {
  folders = listResult.data;
}

const existingSeqs = folders
  .map(f => f?.name || '')
  .map(name => parseInt(name, 10))
  .filter(n => Number.isFinite(n) && n > 0);

const maxSeq = existingSeqs.length > 0 ? Math.max(...existingSeqs) : 0;
const nextSeq = maxSeq + 1;
const publicationId = String(nextSeq).padStart(2, '0');

// ----------------------------------------------------------------------------
// 3. CHEMINS
// ----------------------------------------------------------------------------
const basePath = `${countrySlug}/${agencySlug}/${publicationId}`;

const hasMeaningfulText = hasText && rawText && String(rawText).trim().length > 0;
const isTextOnly = hasMeaningfulText && !hasImage && !hasPdf;
const captionGoesWithImage = hasMeaningfulText && hasImage;
const captionGoesWithPdf = hasMeaningfulText && hasPdf;

const paths = {
  image_file: hasImage ? `${basePath}/${publicationId}.jpg` : null,
  pdf_file: hasPdf ? `${basePath}/${publicationId}.pdf` : null,
  caption_file: hasMeaningfulText ? `${basePath}/caption.txt` : null,
};

// ----------------------------------------------------------------------------
// 4. URLS PUBLIQUES
// ----------------------------------------------------------------------------
const SUPABASE_PUBLIC_URL = $env.SUPABASE_PUBLIC_URL || 'http://localhost:54321';
const BUCKET = 'travel-offer-assets';

function buildPublicUrl(path) {
  if (!path) return null;
  return `${SUPABASE_PUBLIC_URL}/storage/v1/object/public/${BUCKET}/${path}`;
}

const photoUrls = [];
if (paths.image_file) photoUrls.push(buildPublicUrl(paths.image_file));
else if (paths.pdf_file) photoUrls.push(buildPublicUrl(paths.pdf_file));
else if (paths.caption_file) photoUrls.push(buildPublicUrl(paths.caption_file));

// ----------------------------------------------------------------------------
// 5. SORTIE
// ----------------------------------------------------------------------------
// On reprend le payload nettoyé (depuis Compute Slugs), puis on ajoute _storage
return [{
  json: {
    ...finalPayload,
    _content_hash: detectData._content_hash || null,
    _media_type: detectData._media_type || 'image',
    messageId: detectData.messageId || null,
    senderJid: detectData.senderJid || null,
    text: detectData.text || null,
    imageCaption: detectData.imageCaption || null,
    photo_urls: photoUrls.length > 0 ? photoUrls : (finalPayload.photo_urls || []),

    _storage: {
      bucket: BUCKET,
      base_path: basePath,
      job_id: jobId,
      publication_id: publicationId,
      next_seq: nextSeq,
      max_seq_found: maxSeq,
      country_slug: countrySlug,
      agency_slug: agencySlug,
      country_raw: countryRaw,
      agency_name_raw: agencyRaw,

      has_text: hasText,
      has_meaningful_text: hasMeaningfulText,
      has_image: hasImage,
      has_pdf: hasPdf,
      is_text_only: isTextOnly,
      caption_goes_with_image: captionGoesWithImage,
      caption_goes_with_pdf: captionGoesWithPdf,

      raw_text: rawText,
      paths,

      public_urls: {
        image: buildPublicUrl(paths.image_file),
        pdf: buildPublicUrl(paths.pdf_file),
        caption: buildPublicUrl(paths.caption_file),
      },

      // Debug : combien de dossiers ont été listés
      debug_folders_count: folders.length,
      debug_existing_seqs: existingSeqs,
    }
  }
}];

// ============================================================================
// NŒUD : Prepare Caption
// PLACE : Après "Build Storage Path", AVANT "Upload Caption"
// CONDITION : Skip si pas de message WhatsApp (renvoie [])
// RÔLE  : Crée le fichier caption.txt avec le message WhatsApp brut
// ============================================================================

const item = $input.first().json;
const storage = item._storage || {};

// Garde-fou : si pas de message WhatsApp, on n'upload rien
if (!storage.has_meaningful_text) {
  return [];
}

const publicationId = storage.publication_id || 'unknown';
const rawText = storage.raw_text || '';

// Header du fichier caption.txt
const sourceLabel = storage.is_text_only
  ? 'text-only offer (no media)'
  : storage.has_image && storage.has_pdf
    ? 'image + pdf with caption'
    : storage.has_image
      ? 'image with caption'
      : 'pdf with caption';

const header = [
  `# WhatsApp message caption`,
  `# Publication ID: ${publicationId}`,
  `# Source: ${sourceLabel}`,
  `# Country: ${storage.country_slug || 'unknown'}`,
  `# Agency: ${storage.agency_slug || 'unknown'}`,
  `# Parsed at: ${new Date().toISOString()}`,
  `# ============================================================`,
  '',
].join('\n');

const body = String(rawText).trim();
const fullText = header + body;

const base64Content = Buffer.from(fullText, 'utf-8').toString('base64');

return [{
  json: {
    ...item,
    _captionSize: fullText.length,
  },
  binary: {
    caption: {
      data: base64Content,
      mimeType: 'text/plain; charset=utf-8',
      fileName: 'caption.txt',
      fileExtension: 'txt',
    },
  },
}];

// ============================================================================
// NŒUD : Compute Slugs
// PLACE : Entre "Collect & Dynamic Merge" et "List Storage Folder"
// RÔLE  : Normalise le pays (FR uniquement, sans doublons), calcule les slugs
// ============================================================================

const payload = $input.first().json;

// ----------------------------------------------------------------------------
// 1. MAPPING ANGLAIS → FRANÇAIS pour les pays courants
// ----------------------------------------------------------------------------
// On normalise tout en français pour une cohérence Storage + UI
const COUNTRY_EN_TO_FR = {
  'azerbaijan': 'Azerbaïdjan',
  'turkey': 'Turquie',
  'turkiye': 'Turquie',
  'türkiye': 'Turquie',
  'morocco': 'Maroc',
  'tunisia': 'Tunisie',
  'egypt': 'Égypte',
  'spain': 'Espagne',
  'france': 'France',
  'italy': 'Italie',
  'greece': 'Grèce',
  'cyprus': 'Chypre',
  'portugal': 'Portugal',
  'malaysia': 'Malaisie',
  'thailand': 'Thaïlande',
  'maldives': 'Maldives',
  'mauritius': 'Maurice',
  'seychelles': 'Seychelles',
  'indonesia': 'Indonésie',
  'china': 'Chine',
  'japan': 'Japon',
  'south korea': 'Corée du Sud',
  'singapore': 'Singapour',
  'united arab emirates': 'Émirats Arabes Unis',
  'uae': 'Émirats Arabes Unis',
  'dubai': 'Émirats Arabes Unis',
  'qatar': 'Qatar',
  'saudi arabia': 'Arabie Saoudite',
  'jordan': 'Jordanie',
  'lebanon': 'Liban',
  'oman': 'Oman',
  'india': 'Inde',
  'sri lanka': 'Sri Lanka',
  'vietnam': 'Vietnam',
  'algeria': 'Algérie',
  'germany': 'Allemagne',
  'austria': 'Autriche',
  'switzerland': 'Suisse',
  'belgium': 'Belgique',
  'netherlands': 'Pays-Bas',
  'united kingdom': 'Royaume-Uni',
  'uk': 'Royaume-Uni',
  'england': 'Royaume-Uni',
  'russia': 'Russie',
  'georgia': 'Géorgie',
  'armenia': 'Arménie',
  'south africa': 'Afrique du Sud',
  'kenya': 'Kenya',
  'tanzania': 'Tanzanie',
  'mexico': 'Mexique',
  'brazil': 'Brésil',
  'cuba': 'Cuba',
  'dominican republic': 'République Dominicaine',
  'usa': 'États-Unis',
  'united states': 'États-Unis',
  'canada': 'Canada'
};

// ----------------------------------------------------------------------------
// 2. NORMALISATION : on enlève accents pour comparer, mais on garde la version FR officielle
// ----------------------------------------------------------------------------
function stripAccents(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

function normalizeCountryToFrench(country) {
  if (!country || typeof country !== 'string') return null;

  const key = stripAccents(country);

  // Si on connaît la version EN, on retourne la version FR
  if (COUNTRY_EN_TO_FR[key]) {
    return COUNTRY_EN_TO_FR[key];
  }

  // Sinon, on regarde si la version FR existe déjà (en comparant sans accents)
  for (const frName of Object.values(COUNTRY_EN_TO_FR)) {
    if (stripAccents(frName) === key) {
      return frName;
    }
  }

  // Sinon on garde tel quel (premier caractère en majuscule)
  return country.trim().charAt(0).toUpperCase() + country.trim().slice(1).toLowerCase();
}

// ----------------------------------------------------------------------------
// 3. DÉDUPLICATION DES PAYS (sans accents pour comparer)
// ----------------------------------------------------------------------------
const rawCountries = Array.isArray(payload.countries) ? payload.countries : [];
const seen = new Set();
const dedupedCountries = [];

for (const c of rawCountries) {
  const fr = normalizeCountryToFrench(c);
  if (!fr) continue;

  const key = stripAccents(fr);
  if (seen.has(key)) continue;

  seen.add(key);
  dedupedCountries.push(fr);
}

// ----------------------------------------------------------------------------
// 4. SLUGIFICATION
// ----------------------------------------------------------------------------
function slugify(value, fallback) {
  if (!value || typeof value !== 'string') return fallback;
  const slug = value
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
  return slug || fallback;
}

// ----------------------------------------------------------------------------
// 4. PLAN B EXPÉDITEUR WHATSAPP & SLUGIFICATION
// ----------------------------------------------------------------------------
// Récupération des données du message WhatsApp d'origine
const detectData = $('Detect Content & Generate JobId').first().json || {};
const origBody = detectData.originalBody || detectData.originalPayload?.body || {};
const origData = origBody.data || {};
const origKey = origData.key || {};

// Plan B : Nom de profil WhatsApp (pushName)
const pushName = origData.pushName || origBody.pushName || detectData.senderName || null;

// Plan C : Numéro de téléphone de la personne ayant posté dans le groupe
const participant = origKey.participant || origData.participant || detectData.senderJid || '';
const rawPhone = participant.split('@')[0].replace(/\D/g, '');
const senderPhone = rawPhone ? `0${rawPhone.replace(/^213/, '')}` : null;

// --- CASCADE POUR LE NOM D'AGENCE ---
let effectiveAgency = payload.agency_name;
const isAgencyMissing = !effectiveAgency 
  || effectiveAgency.trim() === '' 
  || effectiveAgency.toLowerCase().includes('unknown');

if (isAgencyMissing) {
  if (pushName && pushName.trim() !== '') {
    // PLAN B : Nom de profil WhatsApp de la personne (ex: "Karim - Cap Tourisme")
    effectiveAgency = pushName.trim();
  } else if (senderPhone) {
    // PLAN C : Numéro de téléphone de la personne (ex: "agence-0550123456")
    effectiveAgency = `agence-${senderPhone}`;
  } else {
    effectiveAgency = 'unknown-agency';
  }
}

// On met à jour le nom final pour la base de données et le stockage
payload.agency_name = effectiveAgency;

const firstCountry = dedupedCountries[0] || null;
const countrySlug = slugify(firstCountry, 'unknown-country');
const agencySlug = slugify(effectiveAgency, 'unknown-agency');


// ----------------------------------------------------------------------------
// 5. DÉDUPLICATION DES SERVICES (sans accents)
// ----------------------------------------------------------------------------
function dedupeServices(arr) {
  if (!Array.isArray(arr)) return [];
  const seen = new Set();
  const out = [];
  for (const s of arr) {
    if (typeof s !== 'string' || !s.trim()) continue;
    const key = stripAccents(s);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(s.trim());
  }
  return out;
}

const cleanedServices = {
  included: dedupeServices(payload.services?.included),
  excluded: dedupeServices(payload.services?.excluded)
};

// ----------------------------------------------------------------------------
// 6. SORTIE : payload nettoyé + slugs disponibles
// ----------------------------------------------------------------------------
return [{
  json: {
    ...payload,
    // Debug: number of departures forwarded to the Supabase insert.
    _departures_count: Array.isArray(payload.departures) ? payload.departures.length : 0,
    countries: dedupedCountries,           // SEULEMENT en français, sans doublons
    services: cleanedServices,              // Sans doublons

    // Helpers pour les nœuds suivants (List Storage Folder + Build Storage Path)
    _slugs: {
      country: countrySlug,
      agency: agencySlug,
      country_raw: firstCountry,
      agency_raw: payload.agency_name || null,
      list_prefix: `${countrySlug}/${agencySlug}/`
    }
  }
}];

// ============================================================
// WHATSAPP EARLY FILTER + DEDUP
// Ignore fromMe, non-message events, status/update events
// Deduplicate by message.key.id
// ============================================================

const root = $input.first().json;
const envelope = root.body || {};
const eventType = (envelope.event || '').toLowerCase();
const data = envelope.data || {};
const key = data.key || {};
const message = data.message || {};

// ── 1. Ignore non-message events (only messages.upsert carries real messages)
// Evolution events: messages.upsert, messages.update, connection.update, presence.update, etc.
const isMessageEvent = eventType === 'messages.upsert' || (!eventType && !!data.message);
if (!isMessageEvent) {
  return []; // drop: not a message event (status/update/presence/connection)
}

// ── 2. Ignore status/update events explicitly
if (eventType.includes('update') || eventType.includes('status') || eventType.includes('presence') || eventType.includes('connection')) {
  return [];
}

// ── 3. Ignore fromMe (messages sent by us)
if (key.fromMe === true) {
  return [];
}

// ── 4. Liste blanche des groupes B2B autorisés
const ALLOWED_B2B_GROUPS = [
  '120363417369802582@g.us', // Groupe B2B : R.M Annonces b2b agences de voyages
];

const remoteJid = key.remoteJid || '';
if (!ALLOWED_B2B_GROUPS.includes(remoteJid)) {
  return []; // Ignore tout ce qui ne vient pas de vos groupes B2B autorisés
}


// ── 5. Must contain an actual message payload
const hasAnyContent = !!(
  message.conversation ||
  message.extendedTextMessage ||
  message.imageMessage ||
  message.documentMessage ||
  message?.viewOnceMessage ||
  message?.ephemeralMessage
);
if (!hasAnyContent) {
  return [];
}

// ============================================================
// ── 6. DÉDUPLICATION INTELLIGENTE (Message, Média & Texte)
// ============================================================

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedMessageIds) staticData.processedMessageIds = [];
if (!staticData.processedMediaShas) staticData.processedMediaShas = [];
if (!staticData.processedTextSignatures) staticData.processedTextSignatures = [];

// A. Déduplication par ID de message WhatsApp (même événement réseau)
const messageId = key.id || null;
if (messageId) {
  if (staticData.processedMessageIds.includes(messageId)) {
    return []; // Doublon réseau direct
  }
  staticData.processedMessageIds.push(messageId);
  if (staticData.processedMessageIds.length > 1000) {
    staticData.processedMessageIds.shift();
  }
}

// B. Déduplication par empreinte de média + légende (Flyer Image ou Brochure PDF)
const mediaObj = message.imageMessage 
  || message.documentMessage 
  || message?.viewOnceMessage?.message?.imageMessage
  || message?.ephemeralMessage?.message?.imageMessage;

let fileSha = null;
if (mediaObj?.fileSha256) {
  const raw = mediaObj.fileSha256;
  if (typeof raw === 'string') {
    fileSha = raw;
  } else if (Array.isArray(raw?.data)) {
    fileSha = Buffer.from(raw.data).toString('base64');
  } else if (Buffer.isBuffer(raw) || Array.isArray(raw)) {
    fileSha = Buffer.from(raw).toString('base64');
  } else {
    fileSha = JSON.stringify(raw);
  }
} else if (mediaObj?.mediaKey) {
  fileSha = JSON.stringify(mediaObj.mediaKey);
}

const rawCaption = (message.conversation || message.extendedTextMessage?.text || mediaObj?.caption || '').trim().toLowerCase().replace(/\s+/g, ' ');
const combinedFingerprint = fileSha ? `media:${fileSha}|cap:${rawCaption}` : (rawCaption.length > 30 ? `txt:${rawCaption}` : null);

if (combinedFingerprint) {
  if (staticData.processedMediaShas.includes(combinedFingerprint)) {
    return []; // Même offre (média + légende) déjà vue récemment : STOP immédiat (0 crédit IA)
  }
  staticData.processedMediaShas.push(combinedFingerprint);
  if (staticData.processedMediaShas.length > 2000) {
    staticData.processedMediaShas.shift();
  }
}

// C. Déduplication des annonces textuelles identiques
const rawText = (message.conversation || message.extendedTextMessage?.text || '').trim();
const cleanedText = rawText.toLowerCase().replace(/\s+/g, ' ');

if (cleanedText.length > 50) {
  // Empreinte sur les 150 premiers caractères
  const textSignature = cleanedText.slice(0, 150);
  if (staticData.processedTextSignatures.includes(textSignature)) {
    return []; // Même texte déjà posté récemment
  }
  staticData.processedTextSignatures.push(textSignature);
  if (staticData.processedTextSignatures.length > 1000) {
    staticData.processedTextSignatures.shift();
  }
}

// Pass through unchanged so Detect Content sees the same shape as before
return [{ json: root, binary: $input.first().binary }];

// 1. Récupérer le résultat OCR de LlamaParse
const llamaResult = $input.first().json;
const markdown = llamaResult.markdown
  || llamaResult.content
  || (Array.isArray(llamaResult.pages) ? llamaResult.pages.map(p => p.md || p.text || '').join('\n\n---\n\n') : '')
  || '';

// 2. Récupérer la légende/texte du message WhatsApp s'il existe
let whatsappCaption = '';
try {
  const detectData = $('Detect Content & Generate JobId').first().json;
  whatsappCaption = (detectData.text || detectData.imageCaption || '').trim();
} catch (e) {
  whatsappCaption = '';
}

// 3. Prompt de consolidation intelligente
const PROMPT = `Tu es un moteur d'extraction d'offres de voyage. Transforme ce contenu en JSON structure strict. Retourne UNIQUEMENT du JSON valide. Aucun texte. Aucun markdown. Aucune explication.

MISSION DE CONSOLIDATION :
Tu disposes d'un FLYER (affiche visuelle) et potentiellement d'un TEXTE d'accompagnement (post WhatsApp).
- Le FLYER fait foi en priorité pour les tarifs par chambre (dbl, tpl, sgl), les hôtels et le prix d'appel.
- Le TEXTE sert à enrichir l'itinéraire détaillé, les inclusions/exclusions, les dates/heures de vol et la description.
- Combine intelligemment les deux pour créer l'offre la plus riche et complète possible.

REGLES PAR CHAMP :
title: titre marketing au format : [Destination]-[Saison/Mois]-[Hotel][Catégorie]: exemple : Djerba- été 2026 Joya Paradise 4*
agency_name: nom de l'agence organisatrice (ex: "LOVIVO TRAVEL", "X TOURS", "AGENCE X") ou null
countries: noms de pays en FRANCAIS uniquement (ex: ["Malaisie"])
duration_nights: nombre TOTAL de nuits (ex: 10)
airline: compagnie aérienne (ex: "Air Algérie") ou null
description: résumé court et vendeur (2 phrases max)

ITINERARY (TABLEAU):
[{"day": 1, "title": "Arrivée à Kuala Lumpur", "items": ["Vol Alger - Kuala Lumpur", "Transfert hôtel"]}]

SERVICES (INCLUS / EXCLUS):
included: liste complète des prestations incluses (vol, hôtel, petits déjeuners, transferts, excursions, puce internet...)
excluded: prestations non incluses ou frais personnels

STEPS (Villes + Hôtels + Prix):
Cree un step par ville.
hotels: custom_hotel_name (nom propre de l'hôtel), pricing avec clés exactes: dbl, tpl, sgl, inf, chd_2_6, chd_5_11 (en nombres entiers).

DEPARTURES:
Dates de départs réelles. Format ISO "YYYY-MM-DDTHH:mm:ssZ" ou "YYYY-MM-DDT00:00:00Z". departure_city = "Alger" par défaut.
Voici quelques exemple : 
- dans l'image Format "Du JJ/MM au JJ/MM" : la première date est l'ALLER, la deuxième est le RETOUR. Ici la date d'aller depart = date d'aller arrivée. Idem pour le retour.

PRICING:
is_global_pricing: true si UN seul prix global visible, false si tarifs par type de chambre ou l'annonce contient plusieurs hotel avec des prix differents 
lead_price: tarif adulte d'appel le moins cher (ex: 289000 ou 357000)
status: toujours "draft"
photo_urls: toujours []

SCHEMA JSON A SUIVRE STRICTEMENT :
{"title":null,"agency_id":1,"agency_name":null,"countries":[],"duration_nights":null,"airline":null,"description":null,"itinerary":[{"day":1,"title":"Arrivée","items":["Vol Alger - Destination","Transfert hôtel"]}],"status":"draft","photo_urls":[],"is_global_pricing":false,"global_pricing":null,"lead_price":null,"services":{"included":[],"excluded":[]},"steps":[{"city":null,"step_order":null,"duration_nights":null,"hotels":[{"hotel_id":null,"custom_hotel_name":null,"is_default":false,"pricing":{"dbl":null,"tpl":null,"sgl":null,"inf":null,"chd_2_6":null,"chd_5_11":null}}]}],"departures":[{"departure_city":"Alger","stock":null,"flight_departure_time":"2026-09-02T00:00:00Z","return_flight_departure_time":"2026-09-12T00:00:00Z"}]}`;


// 4. Assemblage du contenu
let contentToAnalyze = '=== 1. CONTENU OCR DU FLYER VISUEL ===\n' + markdown.slice(0, 12000);

if (whatsappCaption && whatsappCaption.length > 5) {
  contentToAnalyze += '\n\n=== 2. TEXTE D\'ACCOMPAGNEMENT DU POST WHATSAPP ===\n' + whatsappCaption.slice(0, 4000);
}

const body = {
  contents: [{
    parts: [{ text: PROMPT + '\n\n' + contentToAnalyze }]
  }],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 8192
  }
};

return [{ json: { geminiBody: body } }];
